    10→    public class AccountDecoder : IRlpObjectDecoder<Account?>, IRlpStreamDecoder<Account?>, IRlpValueDecoder<Account?>
    11→    {
    12→        private readonly bool _slimFormat;
    13→
    14→        public static AccountDecoder Instance => new();
    15→        public static AccountDecoder Slim => new(slimFormat: true);
    16→
    17→        public AccountDecoder() { }
    18→
    19→        public AccountDecoder(bool slimFormat = false)
    20→        {
    21→            _slimFormat = slimFormat;
    22→        }
    23→
    24→        public (Hash256 CodeHash, Hash256 StorageRoot) DecodeHashesOnly(RlpStream rlpStream)
    25→        {
    26→            rlpStream.SkipLength();
    27→            rlpStream.SkipItem();
    28→            rlpStream.SkipItem();
    29→
    30→            Hash256 storageRoot = DecodeStorageRoot(rlpStream);
    31→            Hash256 codeHash = DecodeCodeHash(rlpStream);
    32→
    33→            return (codeHash, storageRoot);
    34→        }
    35→
    36→        public (Hash256 CodeHash, Hash256 StorageRoot) DecodeHashesOnly(ref Rlp.ValueDecoderContext context)
    37→        {
    38→            context.SkipLength();
    39→            context.SkipItem();
    40→            context.SkipItem();
    41→
    42→            Hash256 storageRoot = DecodeStorageRoot(ref context);
    43→            Hash256 codeHash = DecodeCodeHash(ref context);
    44→
    45→            return (codeHash, storageRoot);
    46→        }
    47→
    48→        public Hash256 DecodeStorageRootOnly(ref Rlp.ValueDecoderContext context)
    49→        {
    50→            context.SkipLength();
    51→            context.SkipItem();
    52→            context.SkipItem();
    53→            Hash256 storageRoot = DecodeStorageRoot(context);
    54→            return storageRoot;
    55→        }
    56→
    57→        public Account? Decode(RlpStream rlpStream, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
    58→        {
    59→            int length = rlpStream.ReadSequenceLength();
    60→            if (length == 1)
    61→            {
    62→                return null;
    63→            }
    64→
    65→            UInt256 nonce = rlpStream.DecodeUInt256();
    66→            UInt256 balance = rlpStream.DecodeUInt256();
    67→            Hash256 storageRoot = DecodeStorageRoot(rlpStream);
    68→            Hash256 codeHash = DecodeCodeHash(rlpStream);
    69→            if (ReferenceEquals(storageRoot, Keccak.EmptyTreeHash) && ReferenceEquals(codeHash, Keccak.OfAnEmptyString))
    70→            {
    71→                return new(nonce, balance);
    72→            }
    73→
    74→            return new(nonce, balance, storageRoot, codeHash);
    75→        }
    76→
    77→        public void Encode(RlpStream stream, Account? item, RlpBehaviors rlpBehaviors = RlpBehaviors.None)
    78→        {
