   120→            if (_slimFormat && !account.HasCode)
   121→            {
   122→                rlpStream.EncodeEmptyByteArray();
   123→            }
   124→            else
   125→            {
   126→                rlpStream.Encode(account.CodeHash);
   127→            }
   128→        }
